(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ku"] = {"ui":{"skip":"Derbasî naverokê bibe","back":"← Vegere AI-gile","lang.button":"Ziman: {name}","lang.dialog":"Zimanek hilbijêre","lang.search":"Li zimanan bigere","lang.none":"Tu ziman nehat dîtin","lang.notYet":"{name} hê nehatiye wergerandin","theme.aria":"Di navbera rûpela ronî û tarî de biguherîne","theme.toLight":"Biguherîne rûpela ronî","theme.toDark":"Biguherîne rûpela tarî","index.title":"AI-gile: tîma te ya pêşdebirinê ya AI, li ser yek tabloyê","index.description":"AI-gile tabloyeke kanban e ji bo tîmên kodkirinê yên AI. Ew dixebitin dema tu radizê; ji te re yek komek kurt dimîne: tiştên ku divê biryar bidî, biceribînî û qebûl bikî.","hero.logoAlt":"Îkona tabloya AI-gile","hero.h1.html":"Tîma te ya pêşdebirinê ya AI, li ser yek&nbsp;tabloyê.","hero.alpha":"🐣 Pre-alpha ya girtî","hero.alphaTitle":"Zû û nîvco: spas ji bo ceribandinê!","hero.lede":"Ew dest bi çêkirinê dikin dema tu radizê. Tu şiyar dibî û komek kurt dibînî: çend pirs, çend tiştên ji bo ceribandinê, yek an du almasên mor. Bitikîne, qebûl bike, vegere qehwa xwe.","dl.windows":"Sepana Windows","dl.browser":"Di gerokê de bimeşîne","dl.soon":"Zû tê","dl.notify":"🔔 Gava vebû min agahdar bike","dl.notifySmall":"Alpha an beta","hero.secondary":"Agile, lê tîm qet qehweya stand-up naxwaze. (Dîsa jî stand-up çêdikin.)","pitch.h2":"AI-gile bi çiqas peyvan bixwazî","pitch.lede":"Dirêjahiyekê hilbijêre, ji yek peyvê heta 144. Her dirêjahî danasînek taybet e, ji bo wê mezinahiyê hatiye nivîsandin. Sliderê kaş bike an tuşên tîran bikar bîne.","pitch.rangeLabel":"Dirêjahî bi peyvan","pitch.dice":"🎲 guhertoyeke din","pitch.words.one":"{n} peyv","pitch.words.other":"{n} peyv","pitch.letters.one":"{n} tîp","pitch.letters.other":"{n} tîp","pitch.chars.one":"{n} nîşan","pitch.chars.other":"{n} nîşan","count.line.html.one":"{n} kart niha li ser tabloyê ye","count.line.html.other":"{n} kart niha li ser tabloyê ne","features.aria":"Ew çi dike","f.pile.h":"Yek komek ji bo te","f.pile.html":"<b>Ji bo te</b> her tiştê ku li benda te ye ji hemû projeyan digire: pirs, tiştên ji bo ceribandinê, karên ku tenê mirov dikare bike. Rêza te dibêje çi paşê ye û çiqas dikişîne.","f.sleep.h":"Tîmên ku dema tu radizê dixebitin","f.sleep.p":"Her proje Lead û tîmek ajanên AI heye. Li ser kartekê şirove bike, tîm şiyar dibe, kar dike û bi gavên ku mirovekî westiyayî jî bişopîne vedigerîne.","f.tester.h":"Ceribînerê AI pêşî kontrol dike","f.tester.p":"Berî ku tiştek bigihîje te, ceribîner gavan di kopiyek sepanê de dişopîne û tiştê dîtiye bi dîmenek ekranê nîşan dide. Yên derbasbûyî bi lez bibîne û bi yek tikandinê qebûl bike.","f.proof.h":"Delîl, ne soz","f.proof.p":"Her radestkirin nîşan dide çi guherî: pelan, cudahiyan, dîmenên ekranê. Pêdivî nake ku tu her sepanê vekî da ku bibînî ma qediyaye.","f.chat.h":"Bi Leadên xwe re bipeyive","f.chat.p":"Tabloyeke wekî Discord: ji bo her projeyê yek îkon, ji bo tiştên ku te dixwazin almasên mor. Ji Leadekî re ramanekê binivîse; ew wê dike kart û plan, bi bişkoka ✅ Dest pê bike.","f.tidy.h":"Xwe bi xwe rêkûpêk dike","f.tidy.p":"Kartên girêdayî dibin yek, sernavên tevlihev tên rastkirin, û kontrola token kodê sivik dihêle. Kêmtir tişt ji bo guhertinê, kêmtir tişt ji bo fikirînê.","f.private.h":"Ya te, li ser komputera te","f.private.li1":"Tablo li ser komputera te ya xwe dimeşe û tenê bersiva te dide.","f.private.li2":"Peyamên taybet ên di navbera mirovan de ji dawiyê heta dawiyê şîfrekirî ne.","f.private.li3":"Ne hesab, ne şopîner, ne cookie.","f.lang.h":"Bi zimanê te","f.lang.p":"Zêdetirî 120 ziman, ji Holendî, Weylsî û Japonî heta pirate, Yoda û Klingon, bi vegera bilez bo Îngilîzî ji bo peyvên pêşdebiran.","tl.aria":"Rêzkirina demê ji gotûbêja yekem heta nexşerêyê","tl.h2":"Ji gotûbêja yekem heta tiştê ku tê","tl.lede":"Roj û demên rast, di herêma demê ya te de. Piştî îro ew plan e, bê roj sozdayî.","tl.today":"Îro","tl.planned":"plankirî","tl.cards.one":"{n} kart","tl.cards.other":"{n} kart","join.h2":"Tevlî bibe","join.lede":"AI-gile ji hêla mirovekî biçûk û hejmarek mezin ajanên sebirdar ve tê çêkirin. Niha taybet e, di alphayeke girtî de bi hevalan re. Dixwazî gava vebû biceribînî?","join.btn":"Eleqeyê tomar bike","join.small":"Em ê e-name bişînin, tiştek din na","footer.tag":"AI-gile. Bê şopîner, bê cookie, bê qehweya stand-up.","footer.licence":"Lîsansa karsaziyê","footer.status":"Rewş","form.sending":"Tê şandin…","form.failed":"Nebû: paşê dîsa biceribîne.","form.offline":"Gihîştina AI-gile nebû: paşê dîsa biceribîne.","interest.title":"AI-gile: gava alpha vebû min agahdar bike","interest.description":"E-name xwe bihêle da ku bibihîzî gava alpha an beta ya girtî ya AI-gile vebe.","interest.h1":"🔔 Gava vebû min agahdar bike","interest.lede":"AI-gile di pre-alphayeke girtî de ye. E-name xwe bihêle û em ê carekê binivîsin, gava ji bo te cih hebe.","interest.email":"E-nameya te","interest.which":"Kîjan ceribandin?","interest.alpha":"Alpha ya girtî: zû, hişk, gelek guhertin","interest.beta":"Beta: aramtir, paşê","interest.both":"Yek ji wan, ya ku pêşî were","interest.submit":"Min têxe lîsteyê","interest.thanks":"Spas! Tu di lîsteyê de yî.","licence.title":"AI-gile: lîsansa karsaziyê","licence.description":"AI-gile di karsaziya xwe de bi kar tînî? Lîsansa karsaziyê ya belaş bixwaze.","licence.h1":"📜 Lîsansa karsaziyê","licence.lede":"AI-gile li ser kar bi kar tînî? Ji me re bêje tu kî yî û tu çi dikî. Heke ew qenciyekê dike, lîsans belaş e.","licence.company":"Şirket","licence.website":"Malper","licence.what":"Tu çi dikî","licence.how":"Çawa alîkariya cîhanê dike","licence.email":"E-name","licence.submit":"Daxwaz bike","licence.thanks":"Spas! Em ê bi e-name bersiv bidin.","status.title":"Rewşa AI-gile","status.h1":"Rewşa AI-gile","status.quiet":"Her tişt aram e","status.checking":"Tê kontrolkirin…","status.offline":"Niha nayê gihîştin xizmeta rewşê (dîsa dixebite)","status.updated":"{ago} nûkirî","status.justNow":"niha","status.min":"{n} xulek berê","status.hours":"{n} saet berê","status.days":"{n} roj berê","live.h2":"Bibîne çawa tê avakirin, rasterast","live.caption":"Her kart veşartî ye: hûn şêweya kar dibînin, ne peyvan.","live.watching.one":"rasterast: {n} dibîne","live.watching.other":"rasterast: {n} dibînin","live.offline":"Tabloya rasterast hinekî dimîne. Zû dîsa werin.","live.cols":"Backlog|Ji bo kirinê|Di xebatê de|Tîm kontrol dike|Ji bo te ku test bikî|Ji bo tîmê|Qediya","live.last.now":"Karta dawî nû hat guhastin","live.last.min.one":"Karta dawî {n} deqe berê hat guhastin","live.last.min.other":"Karta dawî {n} deqe berê hat guhastin","live.last.hour.one":"Karta dawî {n} saet berê hat guhastin","live.last.hour.other":"Karta dawî {n} saet berê hat guhastin","live.last.day.one":"Karta dawî {n} roj berê hat guhastin","live.last.day.other":"Karta dawî {n} roj berê hat guhastin"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Radestkirî."]},{"n":2,"texts":["Kanbana robotan.","Ajanên rêkûpêk.","Raman, çêkirî."]},{"n":3,"texts":["Kanban ji robotan re.","Raman dibin taybetmendî.","Kanbana ajanan, belaş."]},{"n":5,"texts":["Tabloya kanban ku ajan dimeşînin.","Tu kartan dinivîsî. Ajan çêdikin.","Belaş, herêmî, ceribandî, hinekî henekî."]},{"n":8,"texts":["Tabloyeke kanban a belaş ku ajanên AI tê de dixebitin.","Ramanekê binivîse. Ajan çêdikin. Tu qebûl dikî.","Agile ji bo yek mirov û gelek robotên sebirdar."]},{"n":13,"texts":["Tabloyeke kanban li ser komputera te ku ajanên AI kartan hildidin û te serokê wan dihêle.","Ramanekê binivîse. Tîmek ajan wê çêdike. Ceribîner kontrol dike. Tu dibêjî erê.","Bê hesab, bê şopîner: tablo, çend robot û tu, yê ku biryarê dide."]},{"n":21,"texts":["AI-gile tabloyeke kanban e ji bo xebata bi ajanên kodkirinê yên AI re. Ew kartan hildidin; tu wan diceribînî û qebûl dikî.","Her proje Lead û tîmek ajanên AI distîne. Li ser her kartekê şirove bike û tîm dest bi kar dike.","Tabloyeke karên kesane ya belaş li ser komputera te ya xwe dimeşe. Karker robot in. Yê ku dibêje erê tu yî."]},{"n":34,"texts":["Tu ramanan datînî ser tabloyê. Tîmek ajanên AI wan dike taybetmendiyên ku dixebitin, diceribîne, û bi gavên ceribandinê vedigerîne. Tu tişt wekî qediyayî nayê hesibandin heya ku tu nebêjî.","AI-gile tabloyeke kanban a malê ye ku Rich bi alîkariyeke mezin a ajanên ku ew niha îdare dike çêkir. Belaş e, li ser komputera te dimeşe û bi hevalan re tê parvekirin, nayê firotin.","Tabloyeke kanban a asayî bifikire, bi stûnên ji Backlog heta Done, tenê kart ji aliyê ajanên AI ve têne hilgirtin. Pêşketinê radigihînin, gava asê dibin dipirsin, û her dem li benda tiliya te ya bi ber jor dimînin."]},{"n":55,"texts":["AI-gile tabloyeke kanban e ku tîma wê ji ajanên AI pêk tê. Her proje Leadek heye ku kar plan dike û alîkarên ku wê çêdikin. Gava taybetmendiyek amade be, ceribînerê AI wê diceribîne û dîmenek ekranê digire, paşê ew dikeve komeka te. Wê qebûl bike, an şirove bike û ew ê ji nû ve li ser bixebitin.","Ew bi riya yek kesî dest pê kir ku dixwest gelek rûniştinên kodkirinê yên AI di heman demê de bişopîne, û bû tabloyeke rast. Li ser makîna te dimeşe, hesabekî naxwaze û şopîner nîne. Ji bo heval û meraqdaran belaş e. Hê qediyayî nîne, ji ber vê yekê li bendê keviyên hişk û carinan şaşmayîneke biçûk be.","Ev guhertoya dilrast e. Hê jî divê ramanên te hebin, û hê jî divê tu encaman kontrol bikî. Tiştê ku AI-gile dike her tişta di navbera wan de ye: kartan di rêzê de digire, gava tu şirove dikî ajanê rast şiyar dike, tam nîşan dide çi guherî, û hemûyan di yek komeka kurt de ji te re kom dike."]},{"n":89,"texts":["AI-gile tabloyeke kanban a belaş e ku tu li ser komputera xwe dimeşînî. Li şûna mirovan, her proje tîmek ajanên AI heye: Leadek ku ramanên te dike kart û plan, û alîkarên ku kartan li gorî girîngiyê hildidin. Gava tiştek hat çêkirin, ceribînerê AI gavên ceribandinê dişopîne û tiştê dîtiye nîşan dide. Paşê di komekê de bi navê Ji bo te li bendê dimîne. Tu qebûl dikî, an şirove dikî û tîm dîsa hewl dide. Tu kart bêyî te nagihîje Done.","Çend taybetmendiyên ku dibe tu li bendê nebî. Nobedariya şevê stûna Ji bo kirinê dema tu radizê tijî dihêle, kartên ku bersiva te nahewînin hildibijêre. Hejmarkerê token nîşan dide ka ajan îro û vê hefteyê çiqas bikar anîn, û No Token Mode ji wan re dibêje xerc nekin. Tu dikarî ji hevalan re peyam bişînî, û peyamên taybet ji dawiyê heta dawiyê şîfrekirî ne. Tablo bi nêzîkî 120 zimanan dipeyive, di nav de Holendî, Flamî, pirate û Klingon. Tu yek ji wan ne bi pere ye, û kes naxwaze wê bifroşe te.","AI-gile projeyeke biçûk û kesane ye, ne şirket e. Rich dixwest çend projeyên kodkirinê yên AI bişopîne bêyî ku her sepanê veke, ji ber vê yekê wî û ajanan tabloyek ji bo vê çêkirin, paşê bi wê tabloyê ya mayî ya xwe çêkirin. Di pre-alphayeke girtî de ye, ango dixebite, bi piranî, ji bo çend hevalan. Rûpelek bihayan, bultena nûçeyan û plana mezinbûnê tune ne. Heke bikêr xuya dike, dikarî bipirsî ku gava hinekî bêtir vebû biceribînî."]},{"n":144,"texts":["AI-gile tabloyeke kanban e ji bo yek mirov û gelek ajanên AI. Li ser komputera te ya xwe dimeşe û bi tevahî belaş e. Tu proje zêde dikî, û her proje Leadek û tîmeke biçûk distîne. Tu bi Lead re dipeyivî, hinekî wekî Discord, û ramanekê vedibêjî; Lead wê dike kart û plan, paşê li bendê dimîne heta tu Dest pê bike bitikînî. Tîm kartan li gorî girîngiyê dikişîne, bi rêzefermaneyeke hêsan a ji bo modelên zimanî hatî çêkirin. Berî ku tiştek ji te re vegere, ceribînerê AI gavan di kopiyek sepanê de dişopîne û dîmenek ekranê lê zêde dike. Karê qediyayî bi pelên guherî û cudahiyê re dikeve komeka te. Tu qebûl dikî, an şirove dihêlî û tîm şiyar dibe û dîsa hewl dide. Tenê tu dikarî kartekê bibî Done. Hemû ev li ser komputera te ne, bê hesab, bê şopîner, bê cookie.","Rojek bi AI-gile re, bi qasî. Êvarê tu çend şirovan dihêlî: ev bişkojk di cihê şaş de ye, ew lîste divê were rêzkirin, gelo em dikarin moda tarî hebin. Tu diçî razanê. Ajan şirovan dixwînin, guhertinan çêdikin, diceribînin û vedigerînin. Heke stûna Ji bo kirinê vala bibe, nobedariya şevê wê ji backlogê bi kartên ku bersiva te nahewînin tijî dike. Serê sibê yek komek kurt maye: du pirs û çend tiştên ji bo ceribandinê, her yek bi gavên ku mirovekî xewalû jî bişopîne û dîmenek ekranê ku dixebite. Tu bi ser wan de diçî, yên baş qebûl dikî û yên mayî vedigerînî. Hejmarkerê token nîşan dide ku ev hemû çiqas bikar anî, û No Token Mode ji bo hefteyên hişk e. Paşê tu taştê dixwî, ku ajan hê nikarin alîkariya wê bikin.","Pêşî, AI-gile çi nîne. Ne startup e, ne ji bo firotinê ye, û kes daneyên te kom nake. Tabloyeke belaş e ku li ser komputera te dimeşe, bê hesab, bê şopîner û bê cookie. Ew çi ye: yek cihê rêkûpêk ji bo dîtina hemû projeyên kodkirinê yên AI bi carekê, bi tîmek ajanan ku kartan dike û te ku biryaran dide. Kartên girêdayî tevhev dike, sernavên tevlihev rast dike, û çavdêriya sivikbûna kodê dike. Bi nêzîkî 120 zimanan dipeyive, ji Holendî û Flamî heta pirate û Klingon. Heval dikarin ji hev re peyam bişînin, taybet û şîfrekirî. Ji hêla Rich û hejmarek mezin ajanên sebirdar ve hatiye çêkirin, bi piranî bi karanîna xwe. Di pre-alphayeke girtî de ye, ji ber vê yekê li hin deveran hişk e. Heke xweş xuya dike, bi rêzdarî bixwaze û dibe ku zû têkevî."]}],"quips":{"1":"Yek peyv. Zîrek. Dibe ku pir zîrek.","3":"Sê peyv. Ji piraniya rûpelên hilberan jixwe dilrasttir.","8":"Heşt peyv. Hê jî ji stand-upê kurttir.","21":"Dirêjahî, bi awayê, xalên çîrokê ne. Bê guman ew in.","55":"Pêncî û pênc peyv. Du kart qediyan dema te ev dixwend.","144":"Ev ya dirêj e. 233 tune ye. Ajan çûne razanê."}},"timeline":{"first-idea.name":"Ramana yekem","first-idea.line":"Gotûbêja pir pêşîn, berî ku kod hebe.","first-board.name":"Tabloya yekem","first-board.line":"Tabloyek ku çêkirina xwe dişopîne: kart, stûn, kaşkirin û berdan, proje.","team-roles.name":"Tîm û rol","team-roles.line":"Profîlên ajanan, şablonên tîmê, cih û kê çi dike.","install.name":"Sazkirin û weşan","install.line":"Zipek ku heval dikare saz bike, nûkirinên xweber, kanal û vegerandin.","usage-saver.name":"Teserûfa bikaranînê","usage-saver.line":"Bipîve ka meşandin çiqas dike, kodê sivik bihêle, sînorê xwe biparêze.","friends.name":"Heval û parvekirin","friends.line":"DMên taybet, relayeke şîfrekirî, vexwendin, rol û projeyên hevpar.","languages.name":"Ziman","languages.line":"Her nivîsa ekranê di pelê zimanekî de, bi Holendî û Flamî pêşî.","ai-tester.name":"Ceribînerê AI","ai-tester.line":"Ceribînerek her radestkirinê pêşî kontrol dike û tiştê dîtiye nîşan dide.","website.name":"Malper","website.line":"aigile.lol, rûpela teaser û ev rêzkirina demê.","streaming.name":"Chat û streaming","streaming.line":"Discord, Twitch, OBS, moda streamer, GIF û emoji.","no-ai.name":"Guhertoya bê AI","no-ai.line":"Tabloyek ji bo kesên ku bê AI kod dikin, û tabloyên giştî.","night-watch.name":"Nobedariya şevê","night-watch.line":"Nobedar û Scrum Master tîman li ser kar dihêlin dema tu radizê.","p-more.name":"Hemû yên din","p-more.line":"Ramanên biçûktir ku hê li benda rêza xwe ne.","p-android.name":"Telefon û Android","p-android.line":"Bi telefonê bigihîje tabloya xwe, paşê bi sepana Android a xwecihî.","p-release.name":"Alpha û pê ve","p-release.line":"Alpha ya girtî, malpera zindî, paşê beta.","p-languages.name":"Zimanên zêdetir","p-languages.line":"Zêdetirî sed ziman, û moda binavbûnê ji bo fêrbûyan.","p-engines.name":"Motorên AI yên zêdetir","p-engines.line":"Ji bo her ajanî Claude, Codex an Gemini hilbijêre.","p-pro.name":"Pratîka pispor","p-pro.line":"Etîketên rîskê, deriyên merge, kartên bûyerê û asteng-parastinan.","p-self.name":"Xwedîkirina te","p-self.line":"Moda westiyayî, bîranînên xwe-lênihêrînê û 4:20.","p-servers.name":"Server û mezinbûn","p-servers.line":"Mîhengên serverê yên giştî, rol û plankirina mezinbûnê.","p-livestream.name":"Zêdeyên streamingê","p-livestream.line":"Chata Twitch, emojiyên taybet û dîtina zindî ya giştî."}};
